<?php
namespace App\Http\Controllers;
use App\Services\{Settings,Content,Backups,Updates,Notifications};
use App\Support\Json;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{DB,Hash,Storage};
use Illuminate\Support\Str;
final class AdminController extends Controller {
    public const MODULES=[1=>'نظرة عامة',2=>'العوالم والمراحل',3=>'نشر أصول المراحل',4=>'المتجر والاقتصاد',5=>'المكافآت اليومية',6=>'اللاعبون والتقدم',7=>'مباني القرية',8=>'المهام والمجموعات',9=>'الإعلانات والتحقق',10=>'الخصوصية والدعم',11=>'تحديثات النظام والنسخ',12=>'الإشعارات والجدولة',13=>'إعدادات النظام'];
    public function __construct(private Settings $settings){}
    public function login(){return view('admin.login');}
    public function authenticate(Request $r){$d=$r->validate(['email'=>'required|email:rfc','password'=>'required|string|max:256']);$a=DB::table('admins')->where('email',strtolower($d['email']))->where('active',true)->first();if(!$a||!Hash::check($d['password'],$a->password))return back()->withErrors(['login'=>'بيانات الدخول غير صحيحة'])->onlyInput('email');$r->session()->regenerate();$r->session()->put(['admin_id'=>$a->id,'admin_reauth_at'=>time()]);$this->settings->audit($a->id,'admin.login');return redirect('/admin');}
    public function logout(Request $r){$r->session()->invalidate();$r->session()->regenerateToken();return redirect('/admin/login');}
    public function reauth(Request $r){$r->validate(['password'=>'required|string|max:256']);if(!Hash::check($r->input('password'),$r->attributes->get('admin')->password))return back()->withErrors(['reauth'=>'كلمة المرور غير صحيحة']);$r->session()->put('admin_reauth_at',time());return back()->with('success','تم تأكيد هويتك لمدة عشر دقائق.');}
    private function allow(Request $r,int $module,bool $write=false): void {abort_unless(isset(self::MODULES[$module]),404);$role=$r->attributes->get('admin')->role;if($role==='owner')return;$allowed=match($role){'content'=>[1,2,3,8,12],'support'=>[1,6,10],'analyst'=>[1,4,5,7,8,9],default=>[]};abort_unless(in_array($module,$allowed,true),403);if($write)abort_unless(($role==='content'&&in_array($module,[2,3,8,12],true))||($role==='support'&&$module===10),403);}
    public function page(Request $r,int $module=1){$this->allow($r,$module);$data=[];$selected=$r->query('id');$q=$r->query('q','');
        switch($module){
            case 1:$data['metrics']=['players'=>DB::table('users')->where('is_guest',false)->count(),'guests'=>DB::table('users')->where('is_guest',true)->where('status','active')->count(),'completed_attempts'=>DB::table('attempts')->where('state','completed')->count(),'published_levels'=>DB::table('levels')->where('published',true)->count(),'queued_jobs'=>DB::table('jobs')->count(),'failed_jobs'=>DB::table('failed_jobs')->count()];$data['records']=DB::table('audits')->orderByDesc('id')->limit(15)->get(['action','subject','created_at']);break;
            case 2:$data['records']=DB::table('levels')->orderBy('world_id')->orderBy('position')->get(['id','display_code','world_id','position','published','active_revision_id']);$data['worlds']=DB::table('worlds')->orderBy('position')->get();break;
            case 3:$data['studio_counts']=['published_studio_documents'=>DB::table('studio_documents')->where('state','published')->count(),'drafts'=>DB::table('studio_documents')->where('state','draft')->count(),'artwork_files'=>DB::table('studio_media')->count()];$data['records']=DB::table('content_revisions')->orderByDesc('created_at')->limit(100)->get(['id','level_id','revision','state','published_at']);break;
            case 4:$data['offers']=config('puzzlequest.rules.store.offers');$data['records']=DB::table('ledger')->orderByDesc('created_at')->limit(30)->get(['user_id','reference','delta','created_at']);break;
            case 5:$data['records']=collect(config('puzzlequest.rules.daily_reward.days'))->map(fn($x)=>(object)$x);break;
            case 6:$users=DB::table('users')->select('id','name','email','is_guest','status','visibility','email_verified_at','created_at');if($q)$users->where(fn($w)=>$w->where('email','like','%'.$q.'%')->orWhere('name','like','%'.$q.'%'));$data['records']=$users->orderByDesc('id')->limit(100)->get();if($selected)$data['ledger']=DB::table('ledger')->where('user_id',$selected)->orderByDesc('created_at')->limit(50)->get();break;
            case 7:$data['buildings']=config('puzzlequest.rules.village.buildings');$data['records']=DB::table('player_buildings')->orderByDesc('updated_at')->limit(50)->get();break;
            case 8:$data['missions']=config('puzzlequest.rules.missions');$data['badges']=config('puzzlequest.rules.achievements.entries');$data['records']=DB::table('claims')->where('type','achievement')->orderByDesc('id')->limit(30)->get(['user_id','reference','created_at']);break;
            case 9:$data['policy']=config('puzzlequest.rules.advertising');$data['records']=DB::table('reward_requests')->orderByDesc('created_at')->limit(50)->get(['id','user_id','type','state','created_at','updated_at']);break;
            case 10:$data['records']=DB::table('support_tickets')->orderByDesc('updated_at')->limit(100)->get(['id','user_id','category','title','state','created_at']);if($selected){$data['ticket']=DB::table('support_tickets')->where('id',$selected)->first();$data['replies']=DB::table('support_replies')->where('ticket_id',$selected)->orderBy('id')->get();}break;
            case 11:$data['records']=DB::table('system_releases')->orderByDesc('created_at')->limit(30)->get(['id','version','state','backup_path','created_at']);$data['version']=app(Updates::class)->version();$data['backups']=collect(Storage::disk('local')->files('backups'))->filter(fn($x)=>str_ends_with($x,'.pqb'))->values();break;
            case 12:$data['records']=DB::table('push_campaigns')->orderByDesc('created_at')->limit(100)->get(['id','category','state','local_wall_time','expires_at','created_at']);$data['deliveries']=DB::table('push_deliveries')->orderByDesc('updated_at')->limit(40)->get(['campaign_id','user_id','timezone','original_due_at','due_at','state','reason']);break;
            case 13:$data['tab']=$r->query('tab','general');$data['settings']=DB::table('settings')->get(['key','secret','updated_at']);$data['legal']=DB::table('legal_documents')->get();$data['admins']=DB::table('admins')->get(['id','name','email','role','active']);$data['runtime']=['version'=>app(Updates::class)->version(),'PHP'=>PHP_VERSION,'Laravel'=>app()->version(),'domain'=>config('app.url'),'Firebase'=>config('puzzlequest.firebase_project'),'Google Audience'=>config('puzzlequest.google_client_id')];break;
        }
        $forms=config('admin_forms.'.$module,[]);
        if($module===2&&!empty($forms[0]['fields'][0]))$forms[0]['fields'][0]['options']=DB::table('worlds')->orderBy('position')->pluck('id')->all();
        return view('admin.module',['module'=>$module,'title'=>self::MODULES[$module],'modules'=>self::MODULES,'admin'=>$r->attributes->get('admin'),'data'=>$data,'forms'=>$forms]);
    }
    public function action(Request $r,int $module){$this->allow($r,$module,true);$admin=$r->attributes->get('admin');$action=$r->string('action')->toString();if(in_array($module,[4,5,6,7,9,11,13],true)&&time()-(int)$r->session()->get('admin_reauth_at',0)>600)return back()->withErrors(['reauth'=>'أكد كلمة المرور أولًا؛ انتهت صلاحية التأكيد.']);
        try{$subject=null;$result=[];switch($action){
            case 'world':abort_unless($module===2,403);$d=$r->validate(['id'=>'required|exists:worlds,id','published'=>'required|boolean']);if($d['published']&&!DB::table('levels')->where('world_id',$d['id'])->where('published',true)->exists())throw new \RuntimeException('لا يمكن نشر عالم بلا مراحل حقيقية منشورة.');DB::table('worlds')->where('id',$d['id'])->update(['published'=>$d['published'],'updated_at'=>now()]);$subject=$d['id'];break;
            case 'level_unpublish':abort_unless($module===2,403);$d=$r->validate(['id'=>'required|exists:levels,id']);DB::table('levels')->where('id',$d['id'])->update(['published'=>false,'updated_at'=>now()]);$subject=$d['id'];break;
            case 'content_upload':abort_unless($module===3,403);$r->validate(['archive'=>'required|file|max:131072']);$result=app(Content::class)->import($r->file('archive')->getRealPath());$subject=$result['id'];break;
            case 'content_publish':abort_unless($module===3,403);$d=$r->validate(['id'=>'required|uuid','device_qa'=>'required|accepted']);DB::transaction(fn()=>app(Content::class)->publish($d['id'],true));$subject=$d['id'];break;
            case 'offer_price':abort_unless($module===4,403);$d=$r->validate(['id'=>'required|in:hint_pack,shuffle_pack,full_image,starter_pack','price'=>'required|integer|between:1,1000000']);$values=$this->settings->get('offer_prices',[]);$values[$d['id']]=$d['price'];$this->settings->set('offer_prices',$values);$subject=$d['id'];break;
            case 'daily_reward':abort_unless($module===5,403);$d=$r->validate(['day'=>'required|integer|between:1,7','coins'=>'required|integer|between:0,1000000','hints'=>'required|integer|between:0,100']);$values=$this->settings->get('daily_rewards',config('puzzlequest.rules.daily_reward.days'));$values[$d['day']-1]=$d;$this->settings->set('daily_rewards',$values);break;
            case 'player_status':abort_unless($module===6&&$admin->role==='owner',403);$d=$r->validate(['id'=>'required|integer|exists:users,id','status'=>'required|in:active,suspended']);DB::transaction(function()use($d){$u=DB::table('users')->where('id',$d['id'])->lockForUpdate()->first();if(!in_array($u->status,['active','suspended'],true))throw new \RuntimeException('حالة الحساب لا تسمح بالتعديل.');DB::table('users')->where('id',$d['id'])->update(['status'=>$d['status'],'updated_at'=>now()]);if($d['status']==='suspended'){DB::table('api_tokens')->where('user_id',$d['id'])->delete();DB::table('push_devices')->where('user_id',$d['id'])->update(['active'=>false]);}});$subject=(string)$d['id'];break;
            case 'building_price':abort_unless($module===7,403);$d=$r->validate(['building'=>'required|in:cottage,windmill','stage'=>'required|integer|between:1,4','price'=>'required|integer|between:1,1000000']);$values=$this->settings->get('building_prices',[]);$values[$d['building'].':'.$d['stage']]=$d['price'];$this->settings->set('building_prices',$values);$subject=$d['building'];break;
            case 'ad_units':abort_unless($module===9,403);$d=$r->validate(['units'=>'required|string|max:500']);$units=array_filter(array_map('trim',explode(',',$d['units'])));foreach($units as$unit)if(!preg_match('~^(?:ca-app-pub-\d+/)?\d+$~D',$unit))throw new \RuntimeException('Ad unit identifier invalid');$this->settings->set('ad_units',array_values($units));break;
            case 'support_reply':abort_unless($module===10,403);$d=$r->validate(['id'=>'required|uuid|exists:support_tickets,id','body'=>'required|string|min:1|max:10000','state'=>'required|in:open,in_progress,waiting_for_player,resolved,closed']);DB::transaction(function()use($d,$admin){$t=DB::table('support_tickets')->where('id',$d['id'])->lockForUpdate()->first();DB::table('support_replies')->insert(['ticket_id'=>$t->id,'admin_id'=>$admin->id,'body'=>$d['body'],'created_at'=>now()]);DB::table('support_tickets')->where('id',$t->id)->update(['state'=>$d['state'],'updated_at'=>now()]);app(Notifications::class)->inbox($t->user_id,'support:'.Str::uuid(),'support',['ar'=>'رد على طلب الدعم','en'=>'Support reply'],['ar'=>'يوجد رد جديد على طلب المساعدة.','en'=>'There is a new reply to your support request.'],['screen'=>'help_support','ticket_id'=>$t->id]);});$subject=$d['id'];break;
            case 'backup':abort_unless($module===11,403);$result=app(Backups::class)->create();break;
            case 'update_verify':abort_unless($module===11,403);$r->validate(['archive'=>'required|file|max:524288']);$result=app(Updates::class)->verify($r->file('archive')->getRealPath());$subject=$result['id'];break;
            case 'update_install':abort_unless($module===11,403);$d=$r->validate(['id'=>'required|uuid','confirm'=>'required|accepted']);$result=app(Updates::class)->install($d['id']);$subject=$d['id'];break;
            case 'campaign':abort_unless($module===12,403);$d=$r->validate(['category'=>'required|in:system,rewards,achievements,progress,account_security,support','ar_title'=>'required|string|max:120','en_title'=>'required|string|max:120','ar_body'=>'required|string|max:500','en_body'=>'required|string|max:500','screen'=>'required|in:inbox,reward_claim_context,achievements,worlds_levels,my_account,help_support,missions_events','wall_time'=>'nullable|date_format:Y-m-d\TH:i','expires_at'=>'required|date|after:now','user_ids'=>'nullable|string|max:2000']);$ids=empty($d['user_ids'])?[]:array_map('intval',explode(',',$d['user_ids']));$id=(string)Str::uuid();DB::table('push_campaigns')->insert(['id'=>$id,'category'=>$d['category'],'title'=>Json::encode(['ar'=>$d['ar_title'],'en'=>$d['en_title']]),'body'=>Json::encode(['ar'=>$d['ar_body'],'en'=>$d['en_body']]),'target'=>Json::encode(['screen'=>$d['screen']]),'audience'=>Json::encode(['user_ids'=>$ids]),'local_wall_time'=>empty($d['wall_time'])?null:str_replace('T',' ',$d['wall_time']),'expires_at'=>\Carbon\CarbonImmutable::parse($d['expires_at'])->utc(),'created_at'=>now(),'updated_at'=>now()]);$subject=$id;break;
            case 'campaign_schedule':abort_unless($module===12,403);$d=$r->validate(['id'=>'required|uuid']);$c=DB::table('push_campaigns')->where('id',$d['id'])->first();if(!$c||$c->state!=='draft')throw new \RuntimeException('Campaign must be a draft');$result=DB::transaction(fn()=>['recipients'=>app(Notifications::class)->schedule($c)]);$subject=$d['id'];break;
            case 'campaign_cancel':abort_unless($module===12,403);$d=$r->validate(['id'=>'required|uuid']);DB::table('push_campaigns')->where('id',$d['id'])->update(['state'=>'cancelled','updated_at'=>now()]);DB::table('push_deliveries')->where('campaign_id',$d['id'])->whereIn('state',['pending','waiting_timezone'])->update(['state'=>'cancelled','updated_at'=>now()]);$subject=$d['id'];break;
            case 'settings':abort_unless($module===13&&$admin->role==='owner',403);$result=$this->saveSettings($r);break;
            case 'legal':abort_unless($module===13&&$admin->role==='owner',403);$d=$r->validate(['slug'=>'required|in:privacy,terms,delete-account,help','locale'=>'required|in:ar,en','version'=>'required|string|max:100','body'=>'required|string|min:100|max:100000','approved'=>'required|accepted']);DB::table('legal_documents')->updateOrInsert(['slug'=>$d['slug'],'locale'=>$d['locale']],['version'=>$d['version'],'body'=>$d['body'],'approved'=>true,'published_at'=>now(),'updated_at'=>now(),'created_at'=>now()]);$subject=$d['slug'].':'.$d['locale'];break;
            case 'admin_create':abort_unless($module===13&&$admin->role==='owner',403);$d=$r->validate(['name'=>'required|string|max:100','email'=>'required|email:rfc|max:254|unique:admins,email','password'=>'required|string|min:12|max:128','role'=>'required|in:owner,content,support,analyst']);DB::table('admins')->insert(['name'=>$d['name'],'email'=>strtolower($d['email']),'password'=>Hash::make($d['password']),'role'=>$d['role'],'created_at'=>now(),'updated_at'=>now()]);break;
            default:abort(404);
        }$this->settings->audit($admin->id,$action,$subject,['module'=>$module,'result_keys'=>array_keys($result)]);return back()->with('success','تم تنفيذ العملية وحفظ سجل المراجعة.')->with('result',$result);
        }catch(\Illuminate\Validation\ValidationException $e){throw $e;}catch(\Symfony\Component\HttpKernel\Exception\HttpExceptionInterface $e){throw $e;}catch(\Throwable $e){$this->settings->audit($admin->id,$action.'.failed',null,['module'=>$module,'exception_type'=>get_class($e)]);return back()->withErrors(['operation'=>$e instanceof \RuntimeException?$e->getMessage():'تعذر التنفيذ دون عرض تفاصيل حساسة.']);}
    }
    private function saveSettings(Request $r): array {
        switch($r->string('kind')->toString()){
            case 'firebase':$r->validate(['credentials'=>'required|json|max:30000']);$c=Json::read($r->input('credentials'));if(($c['project_id']??'')!==config('puzzlequest.firebase_project')||($c['type']??'')!=='service_account'||empty($c['private_key'])||!openssl_pkey_get_private($c['private_key']))throw new \RuntimeException('ملف Service Account غير صالح أو مشروعه مختلف.');$this->settings->set('firebase_credentials',$c,true);return ['configured'=>true,'delivery_verified'=>false];
            case 'smtp':$d=$r->validate(['host'=>'required|string|max:255','port'=>'required|integer|between:1,65535','username'=>'required|string|max:255','password'=>'required|string|max:1000','from'=>'required|email:rfc','scheme'=>'required|in:smtp,smtps']);$this->settings->set('smtp',$d,true);return ['configured'=>true,'delivery_verified'=>false];
            case 'google':$d=$r->validate(['client_id'=>['required','string','max:255','regex:/^[0-9]+-[a-zA-Z0-9]+\.apps\.googleusercontent\.com$/D']]);$this->settings->set('google_client_id',$d['client_id']);return ['configured'=>true,'native_login_verified'=>false];
            case 'release_key':$d=$r->validate(['public_key'=>'required|string|max:200']);if(strlen(base64_decode($d['public_key'],true)?:'')!==32)throw new \RuntimeException('Ed25519 public key must contain32 bytes');$this->settings->set('release_public_key',$d['public_key']);return ['configured'=>true];
            case 'php_cli':$d=$r->validate(['path'=>'required|string|max:500']);if(!is_file($d['path'])||str_contains($d['path'],"\0"))throw new \RuntimeException('PHP CLI path does not exist');$this->settings->set('php_cli_path',$d['path']);return ['configured'=>true];
            case 'legal_gate':$r->validate(['reviewed'=>'required|accepted']);if(DB::table('legal_documents')->where('approved',true)->whereNotNull('published_at')->count()!==8)throw new \RuntimeException('اعتمد وانشر الصفحات الأربع باللغتين أولًا.');$this->settings->set('legal_approved',true);$this->settings->set('delete_enabled',$r->boolean('delete_enabled'));return ['legal_approved'=>true];
            default:throw new \RuntimeException('Unknown settings group');
        }
    }
    public function downloadBackup(Request $r,string $name){abort_unless($r->attributes->get('admin')->role==='owner',403);abort_unless(preg_match('/^[A-Za-z0-9-]+\.pqb$/D',$name)&&Storage::disk('local')->exists('backups/'.$name),404);return Storage::disk('local')->download('backups/'.$name);}
    public function supportImage(Request $r,string $id){$this->allow($r,10);$t=DB::table('support_tickets')->where('id',$id)->first();abort_unless($t&&$t->image_path&&Storage::disk('local')->exists($t->image_path),404);return response()->file(Storage::disk('local')->path($t->image_path),['Cache-Control'=>'no-store']);}
}
